-- The stablecoin_freezes table SQL from the manifest, run as a batch query on raw logs over the window.
-- Same output as datasets/queries/derived-freezes.sql, for the timing comparison.
SELECT block_num, timestamp, evm_decode_hex(tx_hash) AS tx_hash, log_index, symbol, evm_decode_hex(token) AS token_address, event, action, evm_decode_hex(account) AS account, arrow_cast(amount_raw, 'Utf8') AS amount_raw
FROM (
SELECT block_num, timestamp, tx_hash, log_index, token, symbol, 'AddedBlackList' AS event, 'freeze' AS action, d['user'] AS account, arrow_cast(NULL, 'Decimal256(76, 0)') AS amount_raw, CASE symbol WHEN 'USDT' THEN 6 WHEN 'USDC' THEN 6 WHEN 'RLUSD' THEN 18 WHEN 'XAUt' THEN 6 WHEN 'USD1' THEN 18 WHEN 'FDUSD' THEN 18 WHEN 'PAXG' THEN 18 WHEN 'PYUSD' THEN 6 END AS decimals FROM ( SELECT block_num, timestamp, tx_hash, log_index, address AS token, CASE WHEN address = evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7') THEN 'USDT' WHEN address = evm_encode_hex('0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48') THEN 'USDC' WHEN address = evm_encode_hex('0x8292bb45bf1ee4d140127049757c2e0ff06317ed') THEN 'RLUSD' WHEN address = evm_encode_hex('0x68749665ff8d2d112fa859aa293f07a622782f38') THEN 'XAUt' WHEN address = evm_encode_hex('0x8d0d000ee44948fc98c9b98a4fa4921476f08b0d') THEN 'USD1' WHEN address = evm_encode_hex('0xc5f0f7b66764f6ec8c8dff7ba683102295e16409') THEN 'FDUSD' WHEN address = evm_encode_hex('0x45804880de22913dafe09f4980848ece6ecbaf78') THEN 'PAXG' WHEN address = evm_encode_hex('0x6c3ea9036406852006290770bedfcaba0e23a0e8') THEN 'PYUSD' END AS symbol, evm_decode_log(topic1, topic2, topic3, data, 'AddedBlackList(address user)') AS d FROM "{{dataset}}".logs WHERE _block_num BETWEEN 26300743 AND 26322290 AND topic0 = evm_topic('AddedBlackList(address user)') AND address IN (evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7')) ) e UNION ALL  SELECT block_num, timestamp, tx_hash, log_index, token, symbol, 'RemovedBlackList' AS event, 'unfreeze' AS action, d['user'] AS account, arrow_cast(NULL, 'Decimal256(76, 0)') AS amount_raw, CASE symbol WHEN 'USDT' THEN 6 WHEN 'USDC' THEN 6 WHEN 'RLUSD' THEN 18 WHEN 'XAUt' THEN 6 WHEN 'USD1' THEN 18 WHEN 'FDUSD' THEN 18 WHEN 'PAXG' THEN 18 WHEN 'PYUSD' THEN 6 END AS decimals FROM ( SELECT block_num, timestamp, tx_hash, log_index, address AS token, CASE WHEN address = evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7') THEN 'USDT' WHEN address = evm_encode_hex('0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48') THEN 'USDC' WHEN address = evm_encode_hex('0x8292bb45bf1ee4d140127049757c2e0ff06317ed') THEN 'RLUSD' WHEN address = evm_encode_hex('0x68749665ff8d2d112fa859aa293f07a622782f38') THEN 'XAUt' WHEN address = evm_encode_hex('0x8d0d000ee44948fc98c9b98a4fa4921476f08b0d') THEN 'USD1' WHEN address = evm_encode_hex('0xc5f0f7b66764f6ec8c8dff7ba683102295e16409') THEN 'FDUSD' WHEN address = evm_encode_hex('0x45804880de22913dafe09f4980848ece6ecbaf78') THEN 'PAXG' WHEN address = evm_encode_hex('0x6c3ea9036406852006290770bedfcaba0e23a0e8') THEN 'PYUSD' END AS symbol, evm_decode_log(topic1, topic2, topic3, data, 'RemovedBlackList(address user)') AS d FROM "{{dataset}}".logs WHERE _block_num BETWEEN 26300743 AND 26322290 AND topic0 = evm_topic('RemovedBlackList(address user)') AND address IN (evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7')) ) e UNION ALL  SELECT block_num, timestamp, tx_hash, log_index, token, symbol, 'DestroyedBlackFunds' AS event, 'seize' AS action, d['user'] AS account, arrow_cast(d['balance'], 'Decimal256(76, 0)') AS amount_raw, CASE symbol WHEN 'USDT' THEN 6 WHEN 'USDC' THEN 6 WHEN 'RLUSD' THEN 18 WHEN 'XAUt' THEN 6 WHEN 'USD1' THEN 18 WHEN 'FDUSD' THEN 18 WHEN 'PAXG' THEN 18 WHEN 'PYUSD' THEN 6 END AS decimals FROM ( SELECT block_num, timestamp, tx_hash, log_index, address AS token, CASE WHEN address = evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7') THEN 'USDT' WHEN address = evm_encode_hex('0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48') THEN 'USDC' WHEN address = evm_encode_hex('0x8292bb45bf1ee4d140127049757c2e0ff06317ed') THEN 'RLUSD' WHEN address = evm_encode_hex('0x68749665ff8d2d112fa859aa293f07a622782f38') THEN 'XAUt' WHEN address = evm_encode_hex('0x8d0d000ee44948fc98c9b98a4fa4921476f08b0d') THEN 'USD1' WHEN address = evm_encode_hex('0xc5f0f7b66764f6ec8c8dff7ba683102295e16409') THEN 'FDUSD' WHEN address = evm_encode_hex('0x45804880de22913